#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Unit {
    pub symbol: Label,
    pub dimension: Option<Label>,
}
impl Unit {
    pub fn decode(v: &Value, path: &str, ctx: &Ctx) -> Res<Self> {
        Self::decode_fields(rt::Obj::new(v, path)?, ctx)
    }
    pub(crate) fn decode_fields(mut o: rt::Obj<'_>, ctx: &Ctx) -> Res<Self> {
        let path = o.path().to_string();
        let symbol = Label::decode(o.req("symbol")?, &rt::child(&path, "symbol"), ctx)?;
        let dimension = match o.opt("dimension") {
            Some(v) => Some(Label::decode(v, &rt::child(&path, "dimension"), ctx)?),
            None => None,
        };
        o.finish()?;
        Ok(Self { symbol, dimension })
    }
    pub(crate) fn encode_fields(&self) -> Vec<(String, Value)> {
        let mut f: Vec<(String, Value)> = Vec::new();
        f.push(("symbol".to_string(), self.symbol.encode()));
        if let Some(x) = &self.dimension {
            f.push(("dimension".to_string(), x.encode()));
        }
        f
    }
    pub fn encode(&self) -> Value {
        Value::Object(self.encode_fields())
    }
}

