#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StateMachine {
    pub id: Ident,
    pub entity: Ident,
    pub initial: Option<Ident>,
    pub states: Vec<StateDef>,
    pub transitions: Vec<Transition>,
}
impl StateMachine {
    pub fn decode(v: &Value, path: &str, ctx: &Ctx) -> Res<Self> {
        Self::decode_fields(rt::Obj::new(v, path)?, ctx)
    }
    pub(crate) fn decode_fields(mut o: rt::Obj<'_>, ctx: &Ctx) -> Res<Self> {
        let path = o.path().to_string();
        let id = Ident::decode(o.req("id")?, &rt::child(&path, "id"), ctx)?;
        let entity = Ident::decode(o.req("entity")?, &rt::child(&path, "entity"), ctx)?;
        let initial = match o.opt("initial") {
            Some(v) => Some(Ident::decode(v, &rt::child(&path, "initial"), ctx)?),
            None => None,
        };
        let states = rt::list(o.req("states")?, &rt::child(&path, "states"), 0, 256, |e, p| StateDef::decode(e, p, ctx))?;
        let transitions = rt::list(o.req("transitions")?, &rt::child(&path, "transitions"), 0, 1024, |e, p| Transition::decode(e, p, ctx))?;
        o.finish()?;
        Ok(Self { id, entity, initial, states, transitions })
    }
    pub(crate) fn encode_fields(&self) -> Vec<(String, Value)> {
        let mut f: Vec<(String, Value)> = Vec::new();
        f.push(("id".to_string(), self.id.encode()));
        f.push(("entity".to_string(), self.entity.encode()));
        if let Some(x) = &self.initial {
            f.push(("initial".to_string(), x.encode()));
        }
        f.push(("states".to_string(), Value::Array(self.states.iter().map(|e| e.encode()).collect())));
        f.push(("transitions".to_string(), Value::Array(self.transitions.iter().map(|e| e.encode()).collect())));
        f
    }
    pub fn encode(&self) -> Value {
        Value::Object(self.encode_fields())
    }
}

