#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ClaimValue {
    Text(ClaimText),
    Int(ClaimInt),
    Bool(ClaimBool),
    Effect(ClaimEffect),
    ValueType(ClaimValueType),
    Decimal(ClaimDecimal),
    Date(ClaimDate),
    Instant(ClaimInstant),
    Money(ClaimMoney),
}
impl ClaimValue {
    pub fn tag(&self) -> &'static str {
        match self {
            Self::Text(_) => "text",
            Self::Int(_) => "int",
            Self::Bool(_) => "bool",
            Self::Effect(_) => "effect",
            Self::ValueType(_) => "value_type",
            Self::Decimal(_) => "decimal",
            Self::Date(_) => "date",
            Self::Instant(_) => "instant",
            Self::Money(_) => "money",
        }
    }
    pub fn decode(v: &Value, path: &str, ctx: &Ctx) -> Res<Self> {
        let mut o = rt::Obj::new(v, path)?;
        let tag = rt::enum_str(o.req("kind")?, &rt::child(path, "kind"))?;
        match tag {
            "text" => Ok(Self::Text(ClaimText::decode_fields(o, ctx)?)),
            "int" => Ok(Self::Int(ClaimInt::decode_fields(o, ctx)?)),
            "bool" => Ok(Self::Bool(ClaimBool::decode_fields(o, ctx)?)),
            "effect" => Ok(Self::Effect(ClaimEffect::decode_fields(o, ctx)?)),
            "value_type" => Ok(Self::ValueType(ClaimValueType::decode_fields(o, ctx)?)),
            "decimal" => Ok(Self::Decimal(ClaimDecimal::decode_fields(o, ctx)?)),
            "date" => Ok(Self::Date(ClaimDate::decode_fields(o, ctx)?)),
            "instant" => Ok(Self::Instant(ClaimInstant::decode_fields(o, ctx)?)),
            "money" => Ok(Self::Money(ClaimMoney::decode_fields(o, ctx)?)),
            _ => Err(DecodeError::new(&rt::child(path, "kind"), "ir.unknown_variant")),
        }
    }
    pub fn encode(&self) -> Value {
        let mut f = match self {
            Self::Text(x) => x.encode_fields(),
            Self::Int(x) => x.encode_fields(),
            Self::Bool(x) => x.encode_fields(),
            Self::Effect(x) => x.encode_fields(),
            Self::ValueType(x) => x.encode_fields(),
            Self::Decimal(x) => x.encode_fields(),
            Self::Date(x) => x.encode_fields(),
            Self::Instant(x) => x.encode_fields(),
            Self::Money(x) => x.encode_fields(),
        };
        f.push(("kind".to_string(), Value::Str(self.tag().to_string())));
        Value::Object(f)
    }
}

/// An explicit, evidence-linked statement; support and contradiction are kept apart.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Claim {
    pub id: Ident,
    pub subject: Ident,
    pub predicate: ClaimPredicate,
    pub value: ClaimValue,
    pub supports: Vec<Ident>,
    pub contradicts: Vec<Ident>,
    pub certainty: Certainty,
}
impl Claim {
    pub fn decode(v: &Value, path: &str, ctx: &Ctx) -> Res<Self> {
        Self::decode_fields(rt::Obj::new(v, path)?, ctx)
    }
    pub(crate) fn decode_fields(mut o: rt::Obj<'_>, ctx: &Ctx) -> Res<Self> {
        let path = o.path().to_string();
        let id = Ident::decode(o.req("id")?, &rt::child(&path, "id"), ctx)?;
        let subject = Ident::decode(o.req("subject")?, &rt::child(&path, "subject"), ctx)?;
        let predicate = ClaimPredicate::decode(o.req("predicate")?, &rt::child(&path, "predicate"), ctx)?;
        let value = ClaimValue::decode(o.req("value")?, &rt::child(&path, "value"), ctx)?;
        let supports = rt::list(o.req("supports")?, &rt::child(&path, "supports"), 0, 64, |e, p| Ident::decode(e, p, ctx))?;
        let contradicts = rt::list(o.req("contradicts")?, &rt::child(&path, "contradicts"), 0, 64, |e, p| Ident::decode(e, p, ctx))?;
        let certainty = Certainty::decode(o.req("certainty")?, &rt::child(&path, "certainty"), ctx)?;
        o.finish()?;
        Ok(Self { id, subject, predicate, value, supports, contradicts, certainty })
    }
    pub(crate) fn encode_fields(&self) -> Vec<(String, Value)> {
        let mut f: Vec<(String, Value)> = Vec::new();
        f.push(("id".to_string(), self.id.encode()));
        f.push(("subject".to_string(), self.subject.encode()));
        f.push(("predicate".to_string(), self.predicate.encode()));
        f.push(("value".to_string(), self.value.encode()));
        f.push(("supports".to_string(), Value::Array(self.supports.iter().map(|e| e.encode()).collect())));
        f.push(("contradicts".to_string(), Value::Array(self.contradicts.iter().map(|e| e.encode()).collect())));
        f.push(("certainty".to_string(), self.certainty.encode()));
        f
    }
    pub fn encode(&self) -> Value {
        Value::Object(self.encode_fields())
    }
}

