static PARAMNAME_RULE: StrRule = StrRule { pattern: Some("^[a-z][a-z0-9_]{0,47}$"), max_len: 48, text: TextMode::None };
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ParamName(String);
impl ParamName {
    pub fn new(s: &str) -> Res<Self> {
        rt::check_string(s, "", &PARAMNAME_RULE)?;
        Ok(Self(s.to_string()))
    }
    pub fn as_str(&self) -> &str {
        &self.0
    }
    pub fn decode(v: &Value, path: &str, _ctx: &Ctx) -> Res<Self> {
        Ok(Self(rt::string(v, path, &PARAMNAME_RULE)?))
    }
    pub fn encode(&self) -> Value {
        Value::Str(self.0.clone())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParamDef {
    pub r#type: ValueType,
    pub required: bool,
    pub choices: Option<Vec<Label>>,
    pub unit: Option<Unit>,
    pub description: Option<Label>,
}
impl ParamDef {
    pub fn decode(v: &Value, path: &str, ctx: &Ctx) -> Res<Self> {
        Self::decode_fields(rt::Obj::new(v, path)?, ctx)
    }
    pub(crate) fn decode_fields(mut o: rt::Obj<'_>, ctx: &Ctx) -> Res<Self> {
        let path = o.path().to_string();
        let r#type = ValueType::decode(o.req("type")?, &rt::child(&path, "type"), ctx)?;
        let required = rt::boolean(o.req("required")?, &rt::child(&path, "required"))?;
        let choices = match o.opt("choices") {
            Some(v) => Some(rt::list(v, &rt::child(&path, "choices"), 0, 256, |e, p| Label::decode(e, p, ctx))?),
            None => None,
        };
        let unit = match o.opt("unit") {
            Some(v) => Some(Unit::decode(v, &rt::child(&path, "unit"), ctx)?),
            None => None,
        };
        let description = match o.opt("description") {
            Some(v) => Some(Label::decode(v, &rt::child(&path, "description"), ctx)?),
            None => None,
        };
        o.finish()?;
        Ok(Self { r#type, required, choices, unit, description })
    }
    pub(crate) fn encode_fields(&self) -> Vec<(String, Value)> {
        let mut f: Vec<(String, Value)> = Vec::new();
        f.push(("type".to_string(), self.r#type.encode()));
        f.push(("required".to_string(), Value::Bool(self.required.to_owned())));
        if let Some(x) = &self.choices {
            f.push(("choices".to_string(), Value::Array(x.iter().map(|e| e.encode()).collect())));
        }
        if let Some(x) = &self.unit {
            f.push(("unit".to_string(), x.encode()));
        }
        if let Some(x) = &self.description {
            f.push(("description".to_string(), x.encode()));
        }
        f
    }
    pub fn encode(&self) -> Value {
        Value::Object(self.encode_fields())
    }
}

