        f.push(("primitive_set".to_string(), self.primitive_set.encode()));
        f.push(("observation_schema".to_string(), self.observation_schema.encode()));
        f.push(("semantic_schema".to_string(), self.semantic_schema.encode()));
        f.push(("operation_schema".to_string(), self.operation_schema.encode()));
