        f.push(("axes".to_string(), self.axes.encode()));
        f.push(("artifacts".to_string(), Value::Array(self.artifacts.iter().map(|e| e.encode()).collect())));
        f.push(("lineage".to_string(), Value::Array(self.lineage.iter().map(|e| e.encode()).collect())));
        f.push(("migrations".to_string(), Value::Array(self.migrations.iter().map(|e| e.encode()).collect())));
