#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Body {
    Environment(EnvironmentCapabilityManifest),
    Observation(ObservationIR),
    Semantic(SemanticIR),
    Operation(OperationContract),
    Presentation(PresentationIR),
    Version(VersionManifest),
}
impl Body {
    pub fn family(&self) -> &'static str {
        match self {
            Self::Environment(_) => "environment",
            Self::Observation(_) => "observation",
            Self::Semantic(_) => "semantic",
            Self::Operation(_) => "operation",
            Self::Presentation(_) => "presentation",
            Self::Version(_) => "version",
        }
    }
    pub fn encode(&self) -> Value {
        match self {
            Self::Environment(x) => x.encode(),
            Self::Observation(x) => x.encode(),
            Self::Semantic(x) => x.encode(),
            Self::Operation(x) => x.encode(),
            Self::Presentation(x) => x.encode(),
            Self::Version(x) => x.encode(),
        }
    }
    pub fn decode(family: &str, v: &Value, path: &str, ctx: &Ctx) -> Res<Self> {
        match family {
            "environment" => Ok(Self::Environment(EnvironmentCapabilityManifest::decode(v, path, ctx)?)),
            "observation" => Ok(Self::Observation(ObservationIR::decode(v, path, ctx)?)),
            "semantic" => Ok(Self::Semantic(SemanticIR::decode(v, path, ctx)?)),
            "operation" => Ok(Self::Operation(OperationContract::decode(v, path, ctx)?)),
            "presentation" => Ok(Self::Presentation(PresentationIR::decode(v, path, ctx)?)),
            "version" => Ok(Self::Version(VersionManifest::decode(v, path, ctx)?)),
            _ => Err(DecodeError::new(path, "schema.unknown")),
        }
    }
}
